Object.assign(SNIP,{});PRESET_NOTES["l43"]={"Ví dụ: Tổng số bit bằng hàng đợi ưu tiên": "Gộp 1 + 1 = 2, rồi 2 + 2 = 4, rồi 2 + 4 = 6, rồi 5 + 6 = 11. Tổng 2 + 4 + 6 + 11 = 23 bit, so với 33 bit của mã cố định 3 bit.", "Ví dụ: Dựng cây và đọc độ dài mã": "Lưu cây bằng mảng: nút gộp có trai, phai. Độ dài mã của ký tự là độ sâu của lá. Ở đây a dài 1 bit, b và r 3 bit, c và d 3 bit: 5·1 + 2·3 + 2·3 + 1·3 + 1·3 = 23.", "Ví dụ: Giải mã bằng cây": "23 bit giải ra đúng “abracadabra”. Không cần dấu ngăn cách vì không mã nào là tiền tố của mã khác: chạm lá là chắc chắn hết một ký tự.", "Ví dụ: Ký tự hay gặp có mã ngắn": "Ví dụ kinh điển: 224 bit so với 300 bit, tiết kiệm khoảng 25%. Phân bố càng lệch (vài ký tự rất hay gặp) thì Huffman càng lợi.", "Lỗi: mã không phải mã tiền tố": "“01” bị đọc thành “ac”: bit 0 khớp ngay mã của a. Dãy bit này có hai cách hiểu (“b” hoặc “ac”), nên mã không giải mã được. Mã Huffman luôn là mã tiền tố vì ký tự chỉ nằm ở lá."};EX_HINTS["l43"]=[["Đếm số lần xuất hiện của từng chữ, đưa các số khác 0 vào đống min.", "Tổng số bit = tổng trọng số của mọi nút gộp: lấy hai số nhỏ nhất x, y, cộng x + y vào kết quả, đẩy x + y lại.", "Chỉ có một loại ký tự thì vòng lặp không chạy: xử lý riêng, kết quả là độ dài dòng."], ["Dựng cây mã như một trie nhị phân: mỗi mã là một đường đi từ gốc, nút cuối là lá chứa ký tự.", "Giải mã: đi từ gốc theo từng bit; tới lá thì ghi ký tự và quay về gốc.", "Vì là mã tiền tố nên không bao giờ đi qua một lá giữa chừng."], ["Mỗi phần tử trong đống: {{trọng số, chữ nhỏ nhất trong cây}, số hiệu nút}. pair so phần tử đầu trước, bằng thì so phần tử sau: đúng quy tắc của đề.", "Nút gộp mới có khóa {wx + wy, min(chữ nhỏ nhất của hai cây)}; con trái là cây lấy ra trước.", "Đọc mã bằng đệ quy từ gốc: sang trái thêm '0', sang phải thêm '1', tới lá thì ghi lại. Trường hợp một loại chữ phải xử lý riêng."]];
/* ===================== BÀI 43 · Mã Huffman ===================== */
/* Bài 43 · Mã Huffman
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR43=[{label:"Ví dụ: Tổng số bit bằng hàng đợi ưu tiên",input:"",code:"#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // a: 5, b: 2, r: 2, c: 1, d: 1 (số lần xuất hiện trong \"abracadabra\")\n    int f[5] = {5, 2, 2, 1, 1};\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < 5; i++) pq.push(f[i]);\n    int tongBit = 0;\n    while (pq.size() > 1) {\n        int x = pq.top(); pq.pop();    // hai cây nhẹ nhất\n        int y = pq.top(); pq.pop();\n        tongBit += x + y;              // mọi ký tự trong x, y dài thêm 1 bit\n        pq.push(x + y);\n    }\n    cout << tongBit << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"pq"},{type:"vars",names:["x","y","tongBit"]}],py:{code:"import heapq\n\n# a: 5, b: 2, r: 2, c: 1, d: 1 (số lần xuất hiện trong \"abracadabra\")\npq = [5, 2, 2, 1, 1]\nheapq.heapify(pq)\ntong_bit = 0\nwhile len(pq) > 1:\n    x = heapq.heappop(pq)              # hai cây nhẹ nhất\n    y = heapq.heappop(pq)\n    tong_bit += x + y                  # mọi ký tự trong x, y dài thêm 1 bit\n    heapq.heappush(pq, x + y)\nprint(tong_bit)",viz:[{type:"cont",of:"pq",as:"priority_queue"},{type:"vars",names:["x","y","tong_bit"]}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        // a: 5, b: 2, r: 2, c: 1, d: 1 (số lần xuất hiện trong \"abracadabra\")\n        int[] f = { 5, 2, 2, 1, 1 };\n        var pq = new PriorityQueue<int, int>();\n        foreach (int x0 in f) pq.Enqueue(x0, x0);\n        int tongBit = 0;\n        while (pq.Count > 1)\n        {\n            int x = pq.Dequeue();              // hai cây nhẹ nhất\n            int y = pq.Dequeue();\n            tongBit += x + y;                  // mọi ký tự trong x, y dài thêm 1 bit\n            pq.Enqueue(x + y, x + y);\n        }\n        Console.WriteLine(tongBit);\n    }\n}"}},{label:"Ví dụ: Dựng cây và đọc độ dài mã",input:"",code:"#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint w[9], trai[9], phai[9], sau[9];    // nút 0..4 là lá; 5..8 là nút gộp\n\nvoid duyet(int u, int d) {             // d: độ sâu = độ dài mã\n    sau[u] = d;\n    if (u >= 5) {\n        duyet(trai[u], d + 1);\n        duyet(phai[u], d + 1);\n    }\n}\n\nint main() {\n    char kt[5] = {'a', 'b', 'r', 'c', 'd'};\n    int f[5] = {5, 2, 2, 1, 1};\n    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;   // {trọng số, nút}\n    for (int i = 0; i < 5; i++) { w[i] = f[i]; pq.push({f[i], i}); }\n    int moi = 5;\n    while (pq.size() > 1) {\n        int x = pq.top().second; pq.pop();\n        int y = pq.top().second; pq.pop();\n        w[moi] = w[x] + w[y];\n        trai[moi] = x;\n        phai[moi] = y;\n        pq.push({w[moi], moi});\n        moi++;\n    }\n    duyet(moi - 1, 0);\n    for (int i = 0; i < 5; i++) cout << kt[i] << \":\" << sau[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"w"},{type:"cells",of:"sau",ptr:["u"]},{type:"calls"}],py:{code:"import heapq\n\nkt = [\"a\", \"b\", \"r\", \"c\", \"d\"]\nf = [5, 2, 2, 1, 1]\nw = f[:]                               # nút 0..4 là lá; nút gộp thêm vào sau\ntrai = [-1] * 5\nphai = [-1] * 5\npq = [(f[i], i) for i in range(5)]     # (trọng số, nút)\nheapq.heapify(pq)\nwhile len(pq) > 1:\n    _, x = heapq.heappop(pq)\n    _, y = heapq.heappop(pq)\n    w.append(w[x] + w[y])\n    trai.append(x)\n    phai.append(y)\n    heapq.heappush(pq, (w[-1], len(w) - 1))\nsau = [0] * len(w)\n\ndef duyet(u, d):                       # d: độ sâu = độ dài mã\n    sau[u] = d\n    if trai[u] >= 0:\n        duyet(trai[u], d + 1)\n        duyet(phai[u], d + 1)\n\nduyet(len(w) - 1, 0)\nprint(*[kt[i] + \":\" + str(sau[i]) for i in range(5)])",viz:[{type:"cells",of:"w"},{type:"cells",of:"sau",ptr:["u"]},{type:"calls"}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int[] w = new int[9], trai = new int[9], phai = new int[9], sau = new int[9];   // nút 0..4 là lá\n\n    static void Duyet(int u, int d)        // d: độ sâu = độ dài mã\n    {\n        sau[u] = d;\n        if (u >= 5)\n        {\n            Duyet(trai[u], d + 1);\n            Duyet(phai[u], d + 1);\n        }\n    }\n\n    static void Main()\n    {\n        char[] kt = { 'a', 'b', 'r', 'c', 'd' };\n        int[] f = { 5, 2, 2, 1, 1 };\n        var pq = new PriorityQueue<int, int>();      // phần tử: nút; ưu tiên: trọng số * 16 + nút\n        for (int i = 0; i < 5; i++) { w[i] = f[i]; pq.Enqueue(i, f[i] * 16 + i); }\n        int moi = 5;\n        while (pq.Count > 1)\n        {\n            int x = pq.Dequeue();\n            int y = pq.Dequeue();\n            w[moi] = w[x] + w[y];\n            trai[moi] = x;\n            phai[moi] = y;\n            pq.Enqueue(moi, w[moi] * 16 + moi);\n            moi++;\n        }\n        Duyet(moi - 1, 0);\n        for (int i = 0; i < 5; i++) Console.Write(kt[i] + \":\" + sau[i] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Giải mã bằng cây",input:"",code:"#include <iostream>\n#include <string>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // cây mã: a = 0, c = 100, d = 101, b = 110, r = 111\n    // nút trong: 0 (gốc), 1 = \"1\", 2 = \"10\", 3 = \"11\"; ch[u][bit] < 0 là lá -(mã ASCII)\n    int ch[4][2] = {{-'a', 1}, {2, 3}, {-'c', -'d'}, {-'b', -'r'}};\n    string bit = \"01101110100010101101110\";\n    string kq = \"\";\n    int u = 0;\n    for (char b : bit) {\n        int v = ch[u][b - '0'];\n        if (v < 0) {                   // chạm lá: ra một ký tự, quay về gốc\n            kq += (char)(-v);\n            u = 0;\n        } else {\n            u = v;\n        }\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["u","v","kq"]}],py:{code:"# cây mã: a = 0, c = 100, d = 101, b = 110, r = 111\n# nút trong: 0 (gốc), 1 = \"1\", 2 = \"10\", 3 = \"11\"; phần tử là chuỗi thì đó là lá\nch = [[\"a\", 1], [2, 3], [\"c\", \"d\"], [\"b\", \"r\"]]\nbit = \"01101110100010101101110\"\nkq = \"\"\nu = 0\nfor b in bit:\n    v = ch[u][int(b)]\n    if isinstance(v, str):             # chạm lá: ra một ký tự, quay về gốc\n        kq += v\n        u = 0\n    else:\n        u = v\nprint(kq)",viz:[{type:"vars",names:["u","v","kq"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // cây mã: a = 0, c = 100, d = 101, b = 110, r = 111\n        // nút trong: 0 (gốc), 1 = \"1\", 2 = \"10\", 3 = \"11\"; ch[u][bit] < 0 là lá -(mã ký tự)\n        int[][] ch = { new[] { -'a', 1 }, new[] { 2, 3 }, new[] { -'c', -'d' }, new[] { -'b', -'r' } };\n        string bit = \"01101110100010101101110\";\n        string kq = \"\";\n        int u = 0;\n        foreach (char b in bit)\n        {\n            int v = ch[u][b - '0'];\n            if (v < 0)                         // chạm lá: ra một ký tự, quay về gốc\n            {\n                kq += (char)(-v);\n                u = 0;\n            }\n            else\n            {\n                u = v;\n            }\n        }\n        Console.WriteLine(kq);\n    }\n}"}},{label:"Ví dụ: Ký tự hay gặp có mã ngắn",input:"",code:"#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int f[6] = {45, 13, 12, 16, 9, 5};   // tần suất của a, b, c, d, e, f (phần trăm)\n    priority_queue<int, vector<int>, greater<int>> pq;\n    int tong = 0;\n    for (int i = 0; i < 6; i++) { pq.push(f[i]); tong += f[i]; }\n    int bit = 0;\n    while (pq.size() > 1) {\n        int x = pq.top(); pq.pop();\n        int y = pq.top(); pq.pop();\n        bit += x + y;\n        pq.push(x + y);\n    }\n    cout << \"Huffman: \" << bit << \" bit / 100 ky tu\\n\";\n    cout << \"Co dinh 3 bit: \" << 3 * tong << \" bit / 100 ky tu\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"pq"}],py:{code:"import heapq\n\nf = [45, 13, 12, 16, 9, 5]             # tần suất của a, b, c, d, e, f (phần trăm)\npq = f[:]\nheapq.heapify(pq)\nbit = 0\nwhile len(pq) > 1:\n    x = heapq.heappop(pq)\n    y = heapq.heappop(pq)\n    bit += x + y\n    heapq.heappush(pq, x + y)\nprint(\"Huffman:\", bit, \"bit / 100 ky tu\")\nprint(\"Co dinh 3 bit:\", 3 * sum(f), \"bit / 100 ky tu\")",viz:[{type:"cont",of:"pq",as:"priority_queue"}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] f = { 45, 13, 12, 16, 9, 5 };    // tần suất của a, b, c, d, e, f (phần trăm)\n        var pq = new PriorityQueue<int, int>();\n        int tong = 0;\n        foreach (int x0 in f) { pq.Enqueue(x0, x0); tong += x0; }\n        int bit = 0;\n        while (pq.Count > 1)\n        {\n            int x = pq.Dequeue();\n            int y = pq.Dequeue();\n            bit += x + y;\n            pq.Enqueue(x + y, x + y);\n        }\n        Console.WriteLine(\"Huffman: \" + bit + \" bit / 100 ky tu\");\n        Console.WriteLine(\"Co dinh 3 bit: \" + 3 * tong + \" bit / 100 ky tu\");\n    }\n}"}},{label:"Lỗi: mã không phải mã tiền tố",input:"",code:"#include <iostream>\n#include <string>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // a = 0, b = 01, c = 1: mã của a là tiền tố của mã của b\n    string bit = \"01\";                 // định mã hóa chữ \"b\"\n    string kq = \"\";\n    string cur = \"\";\n    for (char c : bit) {\n        cur += c;\n        if (cur == \"0\") { kq += 'a'; cur = \"\"; }\n        else if (cur == \"01\") { kq += 'b'; cur = \"\"; }\n        else if (cur == \"1\") { kq += 'c'; cur = \"\"; }\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["cur","kq"]}],py:{code:"# a = 0, b = 01, c = 1: mã của a là tiền tố của mã của b\nma = {\"0\": \"a\", \"01\": \"b\", \"1\": \"c\"}\nbit = \"01\"                             # định mã hóa chữ \"b\"\nkq = \"\"\ncur = \"\"\nfor c in bit:\n    cur += c\n    if cur in ma:\n        kq += ma[cur]\n        cur = \"\"\nprint(kq)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // a = 0, b = 01, c = 1: mã của a là tiền tố của mã của b\n        string bit = \"01\";                     // định mã hóa chữ \"b\"\n        string kq = \"\", cur = \"\";\n        foreach (char c in bit)\n        {\n            cur += c;\n            if (cur == \"0\") { kq += 'a'; cur = \"\"; }\n            else if (cur == \"01\") { kq += 'b'; cur = \"\"; }\n            else if (cur == \"1\") { kq += 'c'; cur = \"\"; }\n        }\n        Console.WriteLine(kq);\n    }\n}"}}];
