makeEx2(document.getElementById("ex-l43"),sim43,[{t:"Nén văn bản",d:"Đầu vào: một dòng gồm chữ thường a–z, dài 1 … 10^5. Đầu ra: tổng số bit khi mã hóa dòng đó bằng mã Huffman (theo số lần xuất hiện của từng ký tự). Nếu dòng chỉ có một loại ký tự, mỗi ký tự dùng 1 bit.",tests:[{in:"abracadabra",out:"23"},{in:"aaaa",out:"4"},{in:"ab",out:"2"},{in:"aabbbcccc",out:"14"},{in:"thequickbrownfoxjumpsoverthelazydog",out:"160"},{in:"mississippimississippimississippimississippimississippimississippimississippi",out:"147"}],start:"#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n#include <string>\n\nint main() {\n    string s;\n    cin >> s;\n    int dem[26] = {0};\n    for (char c : s) dem[c - 'a']++;\n    priority_queue<long long, vector<long long>, greater<long long>> pq;\n    for (int i = 0; i < 26; i++) if (dem[i] > 0) pq.push(dem[i]);\n    long long tongBit = 0;\n    // một loại ký tự: mỗi ký tự 1 bit; ngược lại gộp hai cây nhẹ nhất\n    cout << tongBit << \"\\n\";\n    return 0;\n}",py:{start:"import heapq\nfrom collections import Counter\n\ns = input()\npq = list(Counter(s).values())\nheapq.heapify(pq)\ntong_bit = 0\n# một loại ký tự: mỗi ký tự 1 bit; ngược lại gộp hai cây nhẹ nhất\nprint(tong_bit)",hints:["Counter(s).values() cho số lần xuất hiện của từng chữ; heapify thành đống min.","Tổng số bit = tổng trọng số của mọi nút gộp: lấy hai số nhỏ nhất x, y, cộng x + y vào kết quả, đẩy x + y lại.","Chỉ có một loại ký tự thì vòng lặp không chạy: xử lý riêng, kết quả là len(s)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        int[] dem = new int[26];\n        foreach (char c in s) dem[c - 'a']++;\n        var pq = new PriorityQueue<long, long>();\n        foreach (int d in dem) if (d > 0) pq.Enqueue(d, d);\n        long tongBit = 0;\n        // một loại ký tự: mỗi ký tự 1 bit; ngược lại gộp hai cây nhẹ nhất\n        Console.WriteLine(tongBit);\n    }\n}",hints:["Đếm số lần xuất hiện của từng chữ, đưa các số khác 0 vào PriorityQueue.","Tổng số bit = tổng trọng số của mọi nút gộp: lấy hai số nhỏ nhất x, y, cộng x + y vào kết quả, đẩy x + y lại.","Chỉ có một loại ký tự thì vòng lặp không chạy: xử lý riêng, kết quả là s.Length."]}},{t:"Giải mã",d:"Đầu vào: dòng 1 là k (1 ≤ k ≤ 26); k dòng sau, mỗi dòng một chữ thường và mã nhị phân của nó (các mã là mã tiền tố, mỗi mã dài 1 … 30); dòng cuối là dãy bit (dài tới 10^6) mã hóa một văn bản. Đầu ra: văn bản gốc.",tests:[{in:"5\na 0\nc 100\nd 101\nb 110\nr 111\n01101110100010101101110",out:"abracadabra"},{in:"3\nx 0\ny 10\nz 11\n0101111100",out:"xyzzyx"},{in:"1\nk 1\n111",out:"kkk"},{in:"6\np 00\nq 01\ns 10\nt 110\nu 1110\nv 1111\n0001101101110111111111110110100100",out:"pqstuvvutsqp"},{in:"6\np 00\nq 01\ns 10\nt 110\nu 1110\nv 1111\n1101110111111011101111110111011111101110111111011101111110111011111101110111111011101111110111011111101110111111011101111110111011111101110111111011101111110111011111101110111111011101111110111011111101110111111011101111000100010001000100010001000100010001000100010001000100010001",out:"tuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvtuvpqpqpqpqpqpqpqpqpqpqpqpqpqpqpq"}],start:"#include <iostream>\n#include <string>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int k;\n    cin >> k;\n    vector<int> c0(1, 0), c1(1, 0);    // cây mã: c0[u], c1[u] là con theo bit 0, 1\n    vector<char> la(1, 0);             // la[u]: ký tự ở lá u (0 nếu không phải lá)\n    for (int i = 0; i < k; i++) {\n        char c;\n        string ma;\n        cin >> c >> ma;\n        // thêm đường đi ma vào cây, đánh dấu lá cuối là c\n    }\n    string bit;\n    cin >> bit;\n    string kq = \"\";\n    // đi từ gốc theo từng bit; chạm lá thì ghi ký tự và quay về gốc\n    cout << kq << \"\\n\";\n    return 0;\n}",py:{start:"k = int(input())\nc0 = [0]                       # cây mã: c0[u], c1[u] là con theo bit 0, 1\nc1 = [0]\nla = [\"\"]                      # la[u]: ký tự ở lá u (\"\" nếu không phải lá)\nfor _ in range(k):\n    c, ma = input().split()\n    # thêm đường đi ma vào cây, đánh dấu lá cuối là c\nbit = input()\nkq = []\n# đi từ gốc theo từng bit; chạm lá thì ghi ký tự và quay về gốc\nprint(\"\".join(kq))",hints:["Dựng cây mã như một trie nhị phân: mỗi mã là một đường đi từ gốc, nút cuối là lá chứa ký tự.","Giải mã: đi từ gốc theo từng bit; tới lá thì ghi ký tự và quay về gốc.","Gom ký tự vào list rồi ''.join ở cuối, đừng cộng chuỗi trong vòng lặp dài."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int k = int.Parse(Console.ReadLine());\n        var c0 = new List<int> { 0 };          // cây mã: c0[u], c1[u] là con theo bit 0, 1\n        var c1 = new List<int> { 0 };\n        var la = new List<char> { '\\0' };     // la[u]: ký tự ở lá u ('\\0' nếu không phải lá)\n        for (int i = 0; i < k; i++)\n        {\n            string[] t = Console.ReadLine().Split();\n            char c = t[0][0];\n            string ma = t[1];\n            // thêm đường đi ma vào cây, đánh dấu lá cuối là c\n        }\n        string bit = Console.ReadLine();\n        var kq = new StringBuilder();\n        // đi từ gốc theo từng bit; chạm lá thì ghi ký tự và quay về gốc\n        Console.WriteLine(kq.ToString());\n    }\n}",hints:["Dựng cây mã như một trie nhị phân: mỗi mã là một đường đi từ gốc, nút cuối là lá chứa ký tự.","Giải mã: đi từ gốc theo từng bit; tới lá thì ghi ký tự và quay về gốc.","Gom kết quả bằng StringBuilder, đừng cộng chuỗi trong vòng lặp dài."]}},{t:"Bảng mã Huffman",d:"Đầu vào: một dòng chữ thường a–z, dài 1 … 10^5. Dựng cây Huffman theo đúng quy tắc: mỗi cây có khóa (trọng số, chữ nhỏ nhất trong cây); mỗi lần lấy hai cây có khóa nhỏ nhất (so trọng số trước, bằng nhau thì so chữ), cây lấy ra trước làm con trái (bit 0), cây sau làm con phải (bit 1). Đầu ra: với mỗi chữ có mặt, theo thứ tự a → z, in một dòng “chữ mã”. Nếu chỉ có một loại chữ, mã của nó là 0.",tests:[{in:"abracadabra",out:"a 0\nb 110\nc 1110\nd 1111\nr 10"},{in:"aaaa",out:"a 0"},{in:"ab",out:"a 0\nb 1"},{in:"aabbbcccc",out:"a 10\nb 11\nc 0"},{in:"thequickbrownfoxjumpsoverthelazydog",out:"a 111100\nb 111101\nc 111110\nd 111111\ne 1110\nf 00000\ng 00001\nh 0001\ni 00100\nj 00101\nk 00110\nl 00111\nm 01000\nn 01001\no 011\np 01010\nq 01011\nr 1000\ns 10010\nt 1010\nu 1011\nv 10011\nw 11000\nx 11001\ny 11010\nz 11011"},{in:"mississippi",out:"i 11\nm 100\np 101\ns 0"}],start:"#include <iostream>\n#include <string>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint w[60], trai[60], phai[60];\nstring ma[60];\n\nint main() {\n    string s;\n    cin >> s;\n    int dem[26] = {0};\n    for (char c : s) dem[c - 'a']++;\n    vector<char> chu;                  // nút 0 .. k-1 là lá của các chữ có mặt\n    priority_queue<pair<pair<int,int>,int>, vector<pair<pair<int,int>,int>>, greater<pair<pair<int,int>,int>>> pq;   // {{trọng số, chữ nhỏ nhất}, nút}\n    for (int c = 0; c < 26; c++) {\n        if (dem[c] == 0) continue;\n        int u = chu.size();\n        chu.push_back('a' + c);\n        w[u] = dem[c];\n        trai[u] = phai[u] = -1;\n        pq.push({{dem[c], c}, u});\n    }\n    // gộp theo quy tắc của đề, rồi đọc mã từ gốc xuống (trái thêm '0', phải thêm '1')\n    for (int i = 0; i < (int)chu.size(); i++) cout << chu[i] << \" \" << ma[i] << \"\\n\";\n    return 0;\n}",py:{start:"import heapq\nfrom collections import Counter\n\ns = input()\ndem = Counter(s)\nchu = sorted(dem)              # nút 0 .. k-1 là lá của các chữ có mặt\nw = [dem[c] for c in chu]\ntrai = [-1] * len(chu)\nphai = [-1] * len(chu)\npq = [(w[i], chu[i], i) for i in range(len(chu))]   # (trọng số, chữ nhỏ nhất, nút)\nheapq.heapify(pq)\nma = [\"\"] * len(chu)\n# gộp theo quy tắc của đề, rồi đọc mã từ gốc xuống (trái thêm \"0\", phải thêm \"1\")\nfor i in range(len(chu)):\n    print(chu[i], ma[i])",hints:["Phần tử trong heapq là bộ (trọng số, chữ nhỏ nhất, số hiệu nút): tuple so phần tử đầu trước, bằng thì so phần tử sau, đúng quy tắc của đề.","Nút gộp mới có khóa (wx + wy, min(mx, my)); con trái là cây lấy ra trước.","Đọc mã bằng đệ quy từ gốc: sang trái thêm '0', sang phải thêm '1', tới lá thì ghi lại. Trường hợp một loại chữ phải xử lý riêng."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static List<long> w = new List<long>();\n    static List<int> trai = new List<int>(), phai = new List<int>();\n\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        int[] dem = new int[26];\n        foreach (char c in s) dem[c - 'a']++;\n        var chu = new List<char>();            // nút 0 .. k-1 là lá của các chữ có mặt\n        var mn = new List<int>();              // chữ nhỏ nhất trong cây của nút\n        var pq = new PriorityQueue<int, long>();   // phần tử: nút; ưu tiên: trọng số * 32 + chữ nhỏ nhất\n        for (int c = 0; c < 26; c++)\n        {\n            if (dem[c] == 0) continue;\n            int u = chu.Count;\n            chu.Add((char)('a' + c));\n            w.Add(dem[c]); trai.Add(-1); phai.Add(-1); mn.Add(c);\n            pq.Enqueue(u, (long)dem[c] * 32 + c);\n        }\n        string[] ma = new string[chu.Count];\n        // gộp theo quy tắc của đề, rồi đọc mã từ gốc xuống (trái thêm \"0\", phải thêm \"1\")\n        for (int i = 0; i < chu.Count; i++) Console.WriteLine(chu[i] + \" \" + ma[i]);\n    }\n}",hints:["Gộp khóa thành một số: trọng số * 32 + chữ nhỏ nhất. So số này đúng bằng so trọng số trước, bằng nhau thì so chữ.","Nút gộp mới có trọng số wx + wy và chữ nhỏ nhất Math.Min(mn[x], mn[y]); con trái là nút lấy ra trước.","Đọc mã bằng đệ quy từ gốc: sang trái thêm '0', sang phải thêm '1', tới lá thì ghi lại. Trường hợp một loại chữ phải xử lý riêng."]}}]);

makeQuiz("quiz43","score43",[{"q": "Mã tiền tố là mã mà?", "o": ["Mọi mã cùng độ dài", "Không mã nào là tiền tố của mã khác", "Mã bắt đầu bằng 0", "Mã ngắn hơn 8 bit"], "a": 1, "e": "Nhờ vậy giải mã được từ trái sang mà không cần dấu ngăn cách."}, {"q": "Mỗi bước, thuật toán Huffman gộp hai cây nào?", "o": ["Nặng nhất", "Nhẹ nhất", "Đầu tiên và cuối cùng", "Ngẫu nhiên"], "a": 1, "e": "Hai ký tự ít gặp nhất nằm sâu nhất trong cây tối ưu."}, {"q": "Tần suất 5, 2, 2, 1, 1. Tổng số bit của mã Huffman?", "o": ["23", "25", "33", "11"], "a": 0, "e": "Các nút gộp 2, 4, 6, 11 có tổng 23."}, {"q": "Trong cây mã, độ dài mã của một ký tự là?", "o": ["Tần suất của nó", "Độ sâu của lá chứa nó", "Số nút của cây", "Số con của gốc"], "a": 1, "e": "Mỗi cạnh từ gốc xuống lá là một bit."}]);

